function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 500000) return 's needs 1 to 5 * 10^5 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  return null;
}

