function lastNonEmptyString(s) {
  let current = s;
  let before = s;
  while (current.length > 0) {
    before = current;
    for (const letter of 'abcdefghijklmnopqrstuvwxyz') {
      const at = current.indexOf(letter);
      if (at !== -1) current = current.slice(0, at) + current.slice(at + 1);
    }
  }
  return before;
}

