function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const make = (length, alphabet) => {
    let text = '';
    for (let i = 0; i < length; i++) text += alphabet[int(0, alphabet.length - 1)];
    return text;
  };
  if (size === 'small') {
    const start = int(0, 22);
    const alphabet = letters.slice(start, start + int(1, 4));
    return [make(int(1, 12), alphabet)];
  }
  const shape = int(0, 2);
  if (shape === 0) return [make(10000, letters)];
  if (shape === 1) return [make(10000, 'xyz')];
  // Mostly one letter with a few others sprinkled in.
  let text = '';
  for (let i = 0; i < 10000; i++) text += rand() < 0.9 ? 'q' : letters[int(0, 25)];
  return [text];
}
